//! 🧪️ Original slot output preserves the input owner, exact identity and scalar stamp until paid donation and closure.
use super::*;
use semio_framework_job::{OriginalJobFixtureCaller,OperationId,Generation};
use semio_framework_value::{RetainedCloneGrant,RetireOwned};
use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;
fn clock()->Option<u64>{Some(1000)}
fn delta(before:RetainedCloneProgress,after:RetainedCloneProgress)->RetainedCloneProgress{RetainedCloneProgress{copied_items:after.copied_items-before.copied_items,copied_bytes:after.copied_bytes-before.copied_bytes,retained_capacity_bytes:after.retained_capacity_bytes-before.retained_capacity_bytes,released_bytes:after.released_bytes-before.released_bytes}}
#[test]
fn original_presented_slot_exact_identity_system_denial_donation_and_full_paid_close(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let policy:serde_json::Value=serde_json::from_str(include_str!("../../../../../../../🔌️plugin/🧪️testing/🎟️caller/🧪️tests/🧫️fixtures/🎟️caller.json")).unwrap();let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../../../../../../../../🔨️modules/🖱️ui/🧪️tests/🧫️fixtures/🎬️media-transport-reservation/🔣️.json")).unwrap();let stock:RetainedCloneGrant=serde_json::from_value(policy["grant"].clone()).unwrap();
 for copy in [1,3,64]{for row in law["cases"].as_array().unwrap(){for cut in [0usize,1,13,64,usize::MAX]{
  let fields=row["identity"].as_array().unwrap();let owner=PresentedMediaOwner{plugin_id:fields[3].as_str().unwrap().into(),controller_id:fields[4].as_str().unwrap().into(),app_instance_id:fields[5].as_u64().unwrap()as u32,parent_document_id:fields[6].as_str().unwrap().into()};let source=PresentedSlotSource{window:fields[0].as_str().unwrap(),node_id:fields[1].as_str().unwrap().parse().unwrap(),key:fields[2].as_str().unwrap(),owner:&owner,rect:PresentedMediaRect{x:1.,y:2.,width:3.,height:4.},clip:PresentedMediaRect{x:1.,y:2.,width:3.,height:4.},order:0,occluded:false};let ((mut original_props,mut caller),bootstrap)=observe(||{let mut props=fixture["cases"][0]["props"].clone();if fields[7].is_null(){props["resource"]=serde_json::Value::Null}(Some(DslValue::from(props)),OriginalJobFixtureCaller::admit(OperationId(policy["operation"].as_u64().unwrap()),Generation(policy["generation"].as_u64().unwrap()),stock,clock,policy["deadlineUs"].as_u64().unwrap(),policy["fuel"].as_u64().unwrap()))});let mut born=bootstrap.requested_bytes;let mut freed=bootstrap.released_bytes;
  caller.turn(stock,|cx|{let identity=(cx.operation(),cx.generation(),cx.clock_source()as usize,cx.deadline_us(),cx.original_recipient_identity());let pointer=original_props.as_ref().unwrap().get("labels").unwrap().get("audio").unwrap().as_str().unwrap().as_ptr();let mut producer=None;let mut output=None;let before=cx.retained_progress();let fuel=cx.fuel_remaining();let(result,heap)=observe(||cx.with_retained_loan(RetainedCloneGrant{maximum_items:0,..cx.retained_grant()},|same|{assert!(!OriginalPresentedSlot::admit(&mut producer,&source,&mut original_props,same)?);Ok(())}));result?;assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(before,cx.retained_progress());assert_eq!(fuel,cx.fuel_remaining());assert!(original_props.is_some());assert!(OriginalPresentedSlot::admit(&mut producer,&source,&mut original_props,cx)?);assert!(original_props.is_none());let producer=producer.as_mut().unwrap();
   for _ in 0..cut{let before=cx.retained_progress();let(result,heap)=observe(||cx.with_retained_loan(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:64.min(cx.retained_grant().maximum_copy_bytes),..cx.retained_grant()},|same|producer.advance(&source,same)));let progress=delta(before,cx.retained_progress());assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));born+=heap.requested_bytes;freed+=heap.released_bytes;if result?{break}assert!(!cx.fuel_exhausted())}
   if cut==usize::MAX{assert!(producer.donate(&mut output,cx)?);let slot=output.as_ref().unwrap();assert_eq!(slot.token,row["token"].as_str().unwrap());assert_eq!(slot.node_id,fields[1].as_str().unwrap());assert_eq!(slot.props.get("labels").unwrap().get("audio").unwrap().as_str().unwrap().as_ptr(),pointer);let resource=slot.props.get("resource").filter(|value|!value.is_null()).map(|value|["kind","controllerId","appInstanceId","parentDocumentId","outputPort","revision","generation"].map(|key|value.get(key)));let wire=serde_json::to_vec(&(slot.window_id.as_str(),slot.node_id.as_str(),slot.node_key.as_str(),slot.plugin_id.as_str(),slot.controller_id.as_str(),slot.app_instance_id,slot.parent_document_id.as_str(),resource)).unwrap();assert_eq!(semio_framework_hash::sha256_hex(&wire),slot.token)}else{let grant=cx.retained_grant();let progress=cx.borrowed_original_cancel_token()?.signal_cancelled_flag_step(grant).unwrap();cx.consume_retained(progress)?;cx.consume_fuel(1)}
   while !producer.terminal_is_empty(){let before=cx.retained_progress();let(result,heap)=observe(||cx.with_retained_loan(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy.min(cx.retained_grant().maximum_copy_bytes),..cx.retained_grant()},|same|producer.close_step(same)));result?;let progress=delta(before,cx.retained_progress());assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));born+=heap.requested_bytes;freed+=heap.released_bytes;assert!(!cx.fuel_exhausted())}let mut output=ControlledRetirement::new(output).unwrap_or_else(|_|unreachable!());while !output.terminal_is_empty(){let before=cx.retained_progress();let(result,heap)=observe(||cx.with_retained_loan(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy.min(cx.retained_grant().maximum_copy_bytes),..cx.retained_grant()},|same|close(&mut output,same)));result?;let progress=delta(before,cx.retained_progress());assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));born+=heap.requested_bytes;freed+=heap.released_bytes;assert!(!cx.fuel_exhausted())}assert_eq!((cx.operation(),cx.generation(),cx.clock_source()as usize,cx.deadline_us(),cx.original_recipient_identity()),identity);Ok(())}).unwrap();let(_,heap)=observe(||caller.retire(stock));born+=heap.requested_bytes;freed+=heap.released_bytes;assert_eq!(born,freed);eprintln!("[DEBUG] original slot paid token/native serde oracle/exact wide ID/original props pointer/deniedSystem0/close{copy}/cut{cut}; GPU not exercised");
 }}}
}
